const aiOutput = $input.item.json;
const original = $('Enrich Leads').item.json;
let raw = aiOutput.text || aiOutput.output || '';
let parsed;
try {
  const cleaned = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { score: 0, reason: 'AI response could not be parsed', outreachDraft: '' };
}
return { json: { ...original, score: Number(parsed.score) || 0, reason: parsed.reason || '', outreachDraft: parsed.outreachDraft || '' } };

function safeItems(name) { try { return $(name).all(); } catch (e) { return []; } }
const generated = safeItems('Generate Sample Leads');
const received = safeItems('Prepare Tally Submission');
const afterDedup = safeItems('Remove Duplicate Leads');
const afterRules = safeItems('Apply ICP Rules');
const results = $input.all().map(i => i.json);
const approved = results.filter(r => r.status === 'approved');
const declined = results.filter(r => r.status === 'declined');
const autoRejected = results.filter(r => r.status === 'auto-rejected-low-score');
const avgScore = results.length ? (results.reduce((s, r) => s + (Number(r.score) || 0), 0) / results.length).toFixed(1) : '0.0';
const sourceLabel = received.length ? 'Tally inquiry webhook' : 'Manual sample data';
const totalReceived = generated.length || received.length;
const approvedNames = approved.map(a => '• ' + a.companyName + ' (score ' + a.score + ')').join('\n') || 'None';
const report = '📊 Lead Pipeline Report\n\nSource: ' + sourceLabel + '\nTotal leads received: ' + totalReceived + '\nAfter dedup: ' + afterDedup.length + '\nPassed ICP rules: ' + afterRules.length + '\nSent for AI scoring: ' + results.length + '\nAvg AI score: ' + avgScore + '\n\n✅ Approved (' + approved.length + '):\n' + approvedNames + '\n\n❌ Declined: ' + declined.length + '\n⏭️ Auto-rejected (low score): ' + autoRejected.length;
return [{ json: { report } }];

const incoming = $json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const data = body.data && typeof body.data === 'object' ? body.data : {};
const fields = Array.isArray(data.fields) ? data.fields : [];
const byLabel = new Map();
for (const field of fields) { if (field && field.label) byLabel.set(String(field.label).trim().toLowerCase(), field.value); if (field && field.key) byLabel.set(String(field.key).trim().toLowerCase(), field.value); }
const read = (...labels) => { for (const label of labels) { const value = byLabel.get(String(label).trim().toLowerCase()); if (value !== undefined && value !== null && value !== '') return value; } return ''; };
const text = (value) => { if (Array.isArray(value)) return value.map((v) => typeof v === 'object' ? (v.text || v.name || v.id || '') : String(v)).filter(Boolean).join(', '); if (value && typeof value === 'object') return value.text || value.name || value.url || JSON.stringify(value); return value === undefined || value === null ? '' : String(value).trim(); };
const number = (value) => { if (typeof value === 'number' && Number.isFinite(value)) return value; const match = text(value).replace(/,/g, '').match(/-?\d+(?:\.\d+)?/); return match ? Number(match[0]) : 0; };
const boolean = (value) => { if (typeof value === 'boolean') return value; return ['true','1','yes','y','checked','agree','i agree','consent'].includes(text(value).toLowerCase()); };
const submissionId = text(data.submissionId || data.responseId || body.eventId || ('unidentified-' + Date.now()));
const eventId = text(body.eventId);
const receivedAt = body.createdAt || data.createdAt || new Date().toISOString();
const contactName = text(read('Full name','Name','Contact name'));
const companyName = text(read('Company name','Company'));
const contactEmail = text(read('Work email','Email','Contact email')).toLowerCase();
const websiteRaw = text(read('Company website','Website','Website URL'));
const website = websiteRaw && /^https?:\/\//i.test(websiteRaw) ? websiteRaw : websiteRaw ? 'https://' + websiteRaw : '';
const industry = text(read('Industry','Business industry'));
const employeeCount = number(read('Approximate number of employees','Employee count','Employees','Company size'));
const country = text(read('Country','Company country'));
const inquiry = text(read('What problem do you need help with?','Problem','Inquiry','Message'));
const consent = boolean(read('I agree to be contacted about this inquiry','Permission to receive a reply','Consent','Opt-in','Opt in'));
const honeypot = text(read('faxNumber','Fax number','Website confirmation'));
const validationErrors = [];
if (!contactName) validationErrors.push('missing contact name');
if (!companyName) validationErrors.push('missing company name');
if (!contactEmail) validationErrors.push('missing work email');
if (contactEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail)) validationErrors.push('invalid work email');
if (!consent) validationErrors.push('contact consent not granted');
if (contactName.length > 100) validationErrors.push('contact name too long');
if (companyName.length > 120) validationErrors.push('company name too long');
if (website.length > 500) validationErrors.push('website too long');
if (country.length > 80) validationErrors.push('country too long');
if (inquiry.length > 3000) validationErrors.push('inquiry too long');
if (employeeCount < 1 || employeeCount > 100000) validationErrors.push('employee count outside allowed range');
if (honeypot) validationErrors.push('honeypot field populated');
const leadKey = (contactEmail || website || companyName || submissionId).toLowerCase().replace(/^https?:\/\//, '').replace(/\/$/, '').trim();
const securityStatus = honeypot || validationErrors.some((e) => e.includes('too long') || e.includes('outside allowed') || e.includes('honeypot')) ? 'suspicious' : validationErrors.length ? 'validation-failed' : 'accepted';
const retentionUntil = new Date(new Date(receivedAt).getTime() + 180 * 24 * 60 * 60 * 1000).toISOString();
const source = text(body.source) || 'Tally';
const sourceType = source === 'n8n-form' ? 'n8n-form' : 'tally-webhook';
return { json: { submissionId, eventId, receivedAt, formId: text(data.formId), formName: text(data.formName), contactName, companyName, workEmail: contactEmail, website, industry, employeeCount, country, inquiry, consent, consentAt: consent ? receivedAt : '', consentVersion: 'privacy-v1-2026-08-25', optOutStatus: 'not_requested', retentionUntil, securityStatus, source, leadKey, status: validationErrors.length ? 'validation-failed' : 'received', validationErrors: validationErrors.join('; '), rawPayload: JSON.stringify(body), employees: employeeCount, contactEmail, sourceType } };

const lead = $json || {};
const errors = [];
if (!lead.contactName) errors.push('full name');
if (!lead.companyName) errors.push('company name');
if (!lead.workEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.workEmail)) errors.push('valid work email');
if (!lead.consent) errors.push('contact consent');
if (lead.securityStatus === 'suspicious') errors.push('security screening');
if (lead.optOutStatus === 'opted_out') errors.push('opt-out suppression');
if (errors.length) throw new Error('Submission stored but not processed: missing, invalid, suspicious, or suppressed ' + errors.join(', ') + '.');
return { json: { companyName: lead.companyName, website: lead.website, industry: lead.industry, employees: lead.employeeCount, country: lead.country, contactEmail: lead.workEmail, contactName: lead.contactName, inquiry: lead.inquiry, leadKey: lead.leadKey, source: lead.source, sourceType: lead.sourceType, submissionId: lead.submissionId, eventId: lead.eventId, consent: lead.consent, consentAt: lead.consentAt, consentVersion: lead.consentVersion, optOutStatus: lead.optOutStatus, retentionUntil: lead.retentionUntil, securityStatus: lead.securityStatus, formId: lead.formId, formName: lead.formName } };

