const input = $json || {};
const now = new Date().toISOString();
const submissionId = 'n8n-form-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
const consentValue = input.consent === true || String(input.consent || '').toLowerCase().includes('yes');
const fields = [
  { key: 'fullName', label: 'Full name', type: 'INPUT_TEXT', value: input.fullName || '' },
  { key: 'companyName', label: 'Company name', type: 'INPUT_TEXT', value: input.companyName || '' },
  { key: 'workEmail', label: 'Work email', type: 'INPUT_EMAIL', value: input.workEmail || '' },
  { key: 'website', label: 'Company website', type: 'INPUT_LINK', value: input.website || '' },
  { key: 'industry', label: 'Industry', type: 'DROPDOWN', value: input.industry || '' },
  { key: 'employees', label: 'Approximate number of employees', type: 'INPUT_NUMBER', value: input.employees || '' },
  { key: 'country', label: 'Country', type: 'INPUT_TEXT', value: input.country || '' },
  { key: 'inquiry', label: 'What problem do you need help with?', type: 'TEXTAREA', value: input.inquiry || '' },
  { key: 'consent', label: 'I agree to be contacted about this inquiry', type: 'CHECKBOXES', value: consentValue },
  { key: 'faxNumber', label: 'faxNumber', type: 'INPUT_TEXT', value: input.faxNumber || '' }
];
return { json: { body: { source: 'n8n-form', eventId: submissionId, eventType: 'FORM_RESPONSE', createdAt: now, data: { responseId: submissionId, submissionId, respondentId: '', formId: 'n8n-client-lead-intake', formName: 'B2B Lead Qualification Inquiry', createdAt: now, fields } } } };

const input = $json || {};
const email = String(input.email || '').trim().toLowerCase();
const companyName = String(input.companyName || '').trim().slice(0, 120);
const reason = String(input.reason || '').trim().slice(0, 1000);
const honeypot = String(input.faxNumber || '').trim();
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Please provide a valid email address.');
if (honeypot) throw new Error('Privacy request rejected by security screening.');
const now = new Date().toISOString();
return { json: { leadKey: email, email, companyName, reason, requestedAt: now, source: 'n8n-opt-out-form', status: 'requested' } };

const lead = $('Prepare Tally Submission').item.json;
const match = $json || {};
const matched = String(match.leadKey || '').toLowerCase() === String(lead.leadKey || '').toLowerCase() && String(match.status || '').toLowerCase() === 'requested';
return { json: { ...lead, optOutStatus: matched ? 'opted_out' : 'not_requested', status: matched ? 'opted-out-suppressed' : lead.status } };
